<?php
$err=[];$editing=isset($item);$schedule=$editing?schedule_for((int)$item['id']):null;$title=$editing?'Edit menu item':'Add menu item';$categories=all('SELECT * FROM categories WHERE active=1 ORDER BY name');
if(post()){
 $name=val('name');$desc=val('description');$ingredients=val('ingredients');$price=val('price');$cat=(int)val('category_id');$plan=null;try{if(!schedules_ready())throw new InvalidArgumentException('The scheduling update is not installed yet. Run the database update first.');$plan=parse_schedule();}catch(InvalidArgumentException $ex){$err[]=$ex->getMessage();}$expiry=$plan['end_at']??'9999-12-31 23:59:59';
 if(!text_valid($name,2,120))$err[]='Enter a dish name (2–120 characters).';
 if(!text_valid($desc,10,3000))$err[]='Describe your dish in 10–3000 characters.';
 if(!text_valid($ingredients,3,2000))$err[]='Add ingredients and allergen information (3–2000 characters).';
 if(!preg_match('/^\d{1,6}(\.\d{1,2})?$/',$price) || (float)$price<1)$err[]='Enter a price between Rs 1 and Rs 999,999.99.';
 if(!one('SELECT id FROM categories WHERE id=? AND active=1',[$cat]))$err[]='Choose an active category set by the administrator.';

 if(!$err){try{db()->beginTransaction();
  $photo=upload('photo','menu',(int)$u['id'],!$editing)??($item['photo_id']??null);
  $paisa=(int)round((float)$price*100);$values=[$cat,$photo,$name,$desc,$ingredients,$paisa,$expiry,now()];
  if($editing)q("UPDATE menu_items SET category_id=?,photo_id=?,name=?,description=?,ingredients=?,price_paisa=?,expires_at=?,updated_at=?,status='published' WHERE id=? AND seller_id=?",[...$values,$item['id'],$u['id']]);
  else q('INSERT INTO menu_items (category_id,photo_id,name,description,ingredients,price_paisa,expires_at,updated_at,seller_id,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)',[...$values,$u['id'],now()]);
  $savedId=$editing?(int)$item['id']:(int)db()->lastInsertId();save_schedule($savedId,$plan);if($plan['mode']==='draft')q("UPDATE menu_items SET status='draft' WHERE id=? AND seller_id=?",[$savedId,$u['id']]);
  db()->commit();flash(match($plan['mode']){'draft'=>'Draft saved. It is not visible to customers.','weekly'=>'Weekly availability saved.','once'=>'Your dish is scheduled.','now'=>'Your dish is now available.'});go('seller/menu.php');
 }catch(InvalidArgumentException $ex){if(db()->inTransaction())db()->rollBack();$err[]=$ex->getMessage();}}
}
function menuval(string $key,mixed $fallback=''): string {global $item;return $_SERVER['REQUEST_METHOD']==='POST'?val($key):(string)($item[$key]??$fallback);}
require ROOT.'/app/workspace-start.php'; ?>
<div class="dash-header"><div><span class="heading-kicker">A LITTLE SOMETHING DELICIOUS</span><h1><?=e($title)?></h1><p class="dash-sub">Give customers a taste of what makes it special.</p></div><a class="pill" href="<?=e(url('seller/menu.php'))?>">← My menu</a></div><section class="panel form-panel"><?php errors($err); ?><?php if(!$categories): ?><div class="alert">There are no active categories yet. Ask the administrator to add one before publishing.</div><?php endif ?><form method="post" enctype="multipart/form-data"><?=csrf()?><?php field('name','Dish name','text','required minlength="2" maxlength="120"',menuval('name')); ?><div class="form-grid"><div class="field"><label for="category_id">Category</label><select id="category_id" name="category_id" required><option value="">Choose a category</option><?php foreach($categories as $c): ?><option value="<?=$c['id']?>" <?=menuval('category_id')==(string)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach ?></select></div><?php field('price','Price (PKR)','number','required min="1" max="999999.99" step="0.01"',$_SERVER['REQUEST_METHOD']==='POST'?val('price'):($editing?number_format($item['price_paisa']/100,2,'.',''):'')); ?></div><?php area('description','Description',menuval('description'),'required minlength="10" maxlength="3000"');area('ingredients','Ingredients and allergens',menuval('ingredients'),'required minlength="3" maxlength="2000" placeholder="e.g. Wheat bun, beef, cheese, egg mayonnaise. Contains wheat, milk and egg."'); ?>
<?php if($editing): ?><img class="form-preview" src="<?=e(image_url($item['photo_id']))?>" alt="Current dish photo"><?php endif ?><?php field('photo',$editing?'Replace photo (optional)':'Dish photo','file',($editing?'':'required ').'accept="image/jpeg,image/png,image/webp"'); ?><p class="hint">JPG, PNG or WebP · Maximum 5 MB.</p><?php require ROOT.'/app/schedule-fields.php'; ?><button class="pill primary space-top" <?=$categories?'':'disabled'?>>Save Menu Item →</button></form></section><?php require ROOT.'/app/workspace-end.php'; ?>
